# Generated by manage.py generate_test_cases.
from django.contrib.auth.models import Permission
from django.contrib.contenttypes.models import ContentType
from django.core.files.uploadedfile import SimpleUploadedFile

from bloomerp.models import ApplicationField, FieldPolicy, File, Policy, RowPolicy
from bloomerp.models.access_control.row_policy_rule import RowPolicyRule
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestDeleteFileComponent(BloomerpComponentTestCase):
    """Tests function `delete_file` from `bloomerp/components/files/actions/delete.py`."""

    view_name = "components_files_delete"

    def get_test_scenarios(self) -> list[RequestScenario]:
        admin_file = self._create_file(name="admin-file.txt")
        linked_customer = self.CustomerModel.objects.first()
        linked_file = self._create_file(
            name="linked-file.txt",
            content_object=linked_customer,
        )

        return [
            RequestScenario(
                name="render delete confirmation for an admin",
                user=self.admin_user,
                view_kwargs={"file_id": admin_file.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        "admin-file.txt" in response.content.decode()
                        and "This action cannot be undone" in response.content.decode()
                    ),
                ),
            ),
            RequestScenario(
                name="delete a file as an admin",
                method="POST",
                user=self.admin_user,
                view_kwargs={"file_id": admin_file.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        response.headers.get("HX-Refresh") == "true"
                        and not File.objects.filter(pk=admin_file.pk).exists()
                    ),
                ),
            ),
            RequestScenario(
                name="delete a linked file with object and files-field permission",
                method="POST",
                user=self.normal_user,
                view_kwargs={"file_id": linked_file.pk},
                prepare=lambda _scenario: self._grant_linked_file_delete_permission(),
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        response.headers.get("HX-Refresh") == "true"
                        and not File.objects.filter(pk=linked_file.pk).exists()
                    ),
                ),
            ),
        ]

    def _create_file(self, *, name: str, content_object=None) -> File:
        return File.objects.create(
            name=name,
            file=SimpleUploadedFile(name, b"test content"),
            persisted=True,
            content_object=content_object,
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )

    def _grant_linked_file_delete_permission(self) -> None:
        content_type = ContentType.objects.get_for_model(self.CustomerModel)
        files_field = ApplicationField.get_by_field(self.CustomerModel, "files")
        view_permission = Permission.objects.get(
            content_type=content_type,
            codename="view_customer",
        )
        delete_permission = Permission.objects.get(
            content_type=content_type,
            codename="delete_customer",
        )

        row_policy = RowPolicy.objects.create(
            name="View linked customer",
            content_type=content_type,
        )
        row_rule = RowPolicyRule.objects.create(
            row_policy=row_policy,
            rule={"connector": "AND", "conditions": []},
        )
        row_rule.permissions.add(view_permission)

        field_policy = FieldPolicy.objects.create(
            name="Delete linked customer files",
            content_type=content_type,
            rule={str(files_field.pk): [delete_permission.codename]},
        )
        policy = Policy.objects.create(
            name="Delete linked file",
            row_policy=row_policy,
            field_policy=field_policy,
        )
        policy.global_permissions.add(view_permission, delete_permission)
        policy.users.add(self.normal_user)
